def kurfile(request, example_directory, jinja_engine):
	result = Kurfile(
		os.path.join(example_directory, request.param),
		jinja_engine
	)

	modify_kurfile(result.data)
	for k in ('train', 'validate', 'test', 'evaluate'):
		if k in result.data and 'data' in result.data[k]:
			for data_source in result.data[k]['data']:
				if 'speech_recognition' in data_source \
					and 'normalization' in data_source['speech_recognition']:
					del data_source['speech_recognition']['normalization']

	result.parse()
	return result

def kurfile(tutorial_yaml):
	result = Kurfile(yaml.load(tutorial_yaml))

	modify_kurfile(result.data)
	for k in ('train', 'validate', 'test', 'evaluate'):
		if k in result.data and 'data' in result.data[k]:
			result.data[k]['data'][0]['pickle'] = os.path.join(
				tempfile.gettempdir(),
				result.data[k]['data'][0]['pickle']
			)

	result.parse()
	return result

def tutorial_data(request, kurfile, num_samples):
	files = []
	for k in ('train', 'validate', 'test', 'evaluate'):
		if k not in kurfile.data:
			continue
		if 'data' not in kurfile.data[k]:
			continue
		if not kurfile.data[k]['data']:
			continue
		files.append(kurfile.data[k]['data'][0]['pickle'])

	for filename in files:
		make_points(num_samples, filename)

	yield

	for filename in files:
		os.unlink(filename)

def ctc_eval_data(ctc_data):
	""" Provides CTC data with only the evaluation-time input data available.
	"""
	for key, source in zip(ctc_data.keys, ctc_data.sources):
		if key == 'TEST_input':
			return BatchProvider(sources={key : source})

def ctc_loss():
	return Ctc(
		input_length='TEST_input_length',
		output_length='TEST_transcription_length',
		output='TEST_transcription'
	)

def source(request, num_entries, chunk_size):
	""" Creates the data Source to test.
	"""
	num_stacks = request.param
	if num_stacks == 0:
		result = VanillaSource(numpy.random.permutation(num_entries)+10)
	else:
		result = StackSource(*[
			VanillaSource(
				numpy.random.permutation(num_entries) + 100*i
			) for i in range(num_stacks)
		])
	if chunk_size is not None:
		result.set_chunk_size(chunk_size)
	return result

def fake_supplier(seed, fake_data):
	result = Mock()
	result.metadata = {'entries' : len(fake_data)}
	result.data = {'data' : fake_data}
	result.kurfile.get_seed.return_value = seed
	result.downselect = partial(SpeechRecognitionSupplier.downselect, result)
	return result

