def conf_file(request):
    env = request.node.get_marker('conf_file')
    kwargs = env.kwargs if env else {}
    result = {
        'content': "",
    }
    result.update(kwargs)

    return result

def tempdir():
    """
    temporary directory that wrapped with `path` class.
    this fixture is for compat with old test implementation.
    """
    return tempfile.mkdtemp()

def temp_path(tmp_path: Path):
    for path in tmp_path.iterdir():
        if path.is_file():
            path.unlink()
        else:
            shutil.rmtree(str(path))
    yield tmp_path

def temp_cache(temp_path):
    from dephell.config import config

    config.attach({'cache': {'path': str(temp_path)}})

def tests_path() -> Path:
    """ Return the absolute Path to 'tests' directory """
    return Path(__file__).parent

def requirements_path(tests_path) -> Path:
    """ Return the absolute Path to 'tests/requirements' """
    return tests_path / Path('requirements')

def repository_path(tests_path) -> Path:
