def execute_listener():

    class ExecuteListener(OrderListener):

        def __init__(self):
            self.listened = False

        def on_execute(self, order: 'Order'):
            self.listened = True

    return ExecuteListener()

def fill_listener():

    class FillListener(OrderListener):

        def __init__(self):
            self.listened = False

        def on_fill(self, order: 'Order', trade: 'Trade'):
            self.listened = True

    return FillListener()

def complete_listener():

    class CompleteListener(OrderListener):

        def __init__(self):
            self.listened = False

        def on_complete(self, order: 'Order'):
            self.listened = True

    return CompleteListener()

def cancel_listener():

    class CancelListener(OrderListener):

        def __init__(self):
            self.listened = False

        def on_cancel(self, order: 'Order'):
            self.listened = True

    return CancelListener()

def exchange(mock_exchange_class):

    exchange = mock_exchange_class.return_value
    exchange.base_instrument = USD
    exchange.id = "fake_id"

    exchange.clock = Clock()

    def quote_price(pair):
        if exchange.clock.step == 0:
            d = {
                ("USD", "BTC"): 7117.00,
                ("USD", "ETH"): 143.00,
                ("USD", "XRP"): 0.22
            }
            return d[(pair.base.symbol, pair.quote.symbol)]
        d = {
            ("USD", "BTC"): 6750.00,
            ("USD", "ETH"): 135.00,
            ("USD", "XRP"): 0.30
        }
        return d[(pair.base.symbol, pair.quote.symbol)]

    exchange.quote_price = mock.Mock(side_effect=quote_price)

    return exchange

def caplog(_caplog: LogCaptureFixture) -> Iterator[LogCaptureFixture]:
    class PropogateHandler(logging.Handler):
        def emit(self, record):
            logging.getLogger(record.name).handle(record)

    handler_id = logger.add(PropogateHandler(), format="{message}")
    yield _caplog
    logger.remove(handler_id)
    assert not _caplog.record_tuples

def display(driver_get_and_display_content):
    with driver_get_and_display_content[1]() as display:
        yield display

def driver_get_and_display_content(
    driver: Chrome,
    server: AbstractRenderServer,
    server_url: str,
    mount: Callable[..., None],
) -> Iterator[Callable[[Union[ElementConstructor, AbstractElement], str], None]]:
    """A function for displaying an element using the current web driver."""
    return create_selenium_page_get_and_display_context(
        driver, server, server_url, mount
    )

def driver_wait(driver: Chrome) -> WebDriverWait:
    """A :class:`WebDriverWait` object for the current web driver"""
    return WebDriverWait(driver, 3)

def driver(create_driver: Callable[[], Chrome]) -> Chrome:
    """A Selenium web driver"""
    return create_driver()

def create_driver(driver_is_headless):
    """A Selenium web driver"""
    with ExitStack() as exit_stack:

        def create():
            return exit_stack.enter_context(
                open_selenium_chrome_driver(headless=driver_is_headless)
            )

        yield create

def mount(
    mount_and_server: Tuple[Callable[..., None], AbstractRenderServer]
) -> Callable[..., None]:
    """A function for mounting an element to the IDOM server's layout"""
    return mount_and_server[0]

def server(
    mount_and_server: Tuple[Callable[..., None], AbstractRenderServer]
) -> Iterator[AbstractRenderServer]:
    """An IDOM server"""
    server = mount_and_server[1]
    if not isinstance(server, SanicRenderServerWithLastError):
        raise TypeError(
            "Servers for testing must be SanicRenderServerWithLastError instances"
        )
    time.sleep(1)  # wait for server to start
    yield server
    server.stop()

def mount_and_server(
    host: str, port: int
) -> Tuple[Callable[..., None], AbstractRenderServer]:
    """An IDOM layout mount function and server as a tuple

    The ``mount`` and ``server`` fixtures use this.
    """
    return create_sanic_hotswap_mount_and_server(PerClientStateServer, host, port)

def host() -> str:
    """The hostname for the IDOM server setup by ``mount_and_server``"""
    return "127.0.0.1"

def port(host: str) -> int:
    """The port for the IDOM server setup by ``mount_and_server``"""
    return find_available_port(host)

def client_implementation():
    original = idom.client.current
    try:
