def ray_8_cpus_gpus():
    if "CUDA_VISIBLE_DEVICES" in os.environ:
        if len(os.environ["CUDA_VISIBLE_DEVICES"].split(",")) < 8:
            pytest.skip("Avoiding mismatched GPU machine.")
    ray.init(num_cpus=8, num_gpus=8)
    yield
    # The code after the yield will run as teardown code.
    ray.shutdown()

def sparkdf(spark):       

    data = [
         {"surname": "smith", "firstname": "john"},
         {"surname": "smith", "firstname": "john"}, 
         {"surname": "smithe","firstname": "john"}


    ]

    dfpd = pd.DataFrame(data)
    df = spark.createDataFrame(dfpd)
    yield df

def str_comp_data(spark):

    rows = [
        {
            "str_col_l": "these strings are equal",
            "str_col_r": "these strings are equal",
        },
        {
            "str_col_l": "these strings are almost equal",
            "str_col_r": "these strings are almos equal",
        },
        {
            "str_col_l": "these strings are almost equal",
            "str_col_r": "not the same at all",
        },
        {"str_col_l": "these strings are almost equal", "str_col_r": None},
        {"str_col_l": None, "str_col_r": None},
    ]
    df = spark.createDataFrame(Row(**x) for x in rows)
    df.createOrReplaceTempView("str_comp")
    return df

def df(spark):

    rows = []
    for i in range(1000):
        r = {
            "match_probability": random.uniform(0, 1),
            "tf_adjusted_match_prob": random.uniform(0, 1),
        }
        rows.append(r)

    df = spark.createDataFrame(Row(**x) for x in rows)
    yield df

def django_db_modify_db_settings(django_db_modify_db_settings,):
    os.environ['ENV'] = 'test'
    settings.DATABASES['default'] = {
        'ENGINE':   'django.db.backends.sqlite3',
        'NAME':     ':memory:'
    }

def mock_redis(request):
    mocks = ['photonix.classifiers.base_model.Lock',
             'photonix.classifiers.style.model.Lock',
             'photonix.classifiers.object.model.Lock']
    mocks = [mock.patch(x, mock.MagicMock()) for x in mocks]
    for m in mocks:
        m.start()
    yield
    for m in mocks:
        m.stop()

