    def example(conf: str, pos_args: Optional[List[str]] = None) -> str:
        tox_ini_file = tmp_path / "tox.ini"
        tox_ini_file.write_text(f"[testenv:py]\nenv={conf}\n")
        tox_ini = ToxIni(tox_ini_file)
        config = Config(tox_ini, overrides=[], root=tmp_path, pos_args=pos_args, work_dir=tmp_path)
        loader = config.get_env("py").loaders[0]
        return loader.load(key="env", of_type=str, conf=config, env_name="a")

    return example  # noqa

def example(tox_ini_conf: ToxIniCreator) -> EnvConfigCreator:
    def func(conf: str) -> ConfigSet:
        config = tox_ini_conf(f"""[tox]\nenv_list = a\n[testenv]\n{conf}\n""")
        env_config = config.get_env("a")
        return env_config

    return func

def _conf_builder(tox_ini_conf: ToxIniCreator) -> ConfBuilder:
    def _make(conf_str: str) -> ConfigSet:
        return tox_ini_conf(f"[tox]\nenvlist=py39\n[testenv]\n{conf_str}").get_env("py39")

    return _make

def value_error() -> Callable[[str], str]:
    def _fmt(msg: str) -> str:
        return f'ValueError("{msg}"{"," if sys.version_info < (3, 7) else ""})'

    return _fmt

def tox_ini_conf(tmp_path: Path, monkeypatch: MonkeyPatch) -> ToxIniCreator:
    def func(conf: str, override: Optional[Sequence[Override]] = None) -> Config:
        dest = tmp_path / "c"
        dest.mkdir()
        config_file = dest / "tox.ini"
        config_file.write_bytes(conf.encode("utf-8"))
        with monkeypatch.context() as context:
            context.chdir(tmp_path)
        return make_config(Parsed(work_dir=dest, override=override or [], config_file=config_file), pos_args=[])

    return func

def base_info() -> Dict[str, Any]:
    return {
        "reportversion": "1",
        "toxversion": __version__,
        "platform": sys.platform,
        "host": socket.getfqdn(),
    }

def tox_wheel(tmp_path_factory: TempPathFactory) -> Path:
    # takes around 3.2s
    package: Optional[Path] = None
    if "TOX_PACKAGE" in os.environ:
        env_tox_pkg = Path(os.environ["TOX_PACKAGE"])
        if env_tox_pkg.exists() and env_tox_pkg.suffix == ".whl":
            package = env_tox_pkg
    if package is None:  # pragma: no cover
        # when we don't get a wheel path injected, build it (for example when running from an IDE)
        package = build_wheel(tmp_path_factory.mktemp("dist"), Path(__file__).parents[1])
    return package

