def assert_equals_stdout(capsys):
    def strip(string): return "".join(string.split())

    def should_equal(expected: str, file_path: str):
        out = capsys.readouterr().out
        assert strip(out) == strip(expected), file_path
    return should_equal

def no_warnings(caplog):
    yield
    for when in ("setup", "call"):
        messages = [
            x.message for x in caplog.get_records(when) if x.levelno == logging.WARNING
        ]
        if messages:
            pytest.fail(
                "warning messages encountered during testing: {}".format(messages)
            )

def logs_warning(caplog):
    yield
    messages = [
        x.message for x in caplog.get_records("call") if x.levelno == logging.WARNING
    ]
    if not messages:
        pytest.fail(
            f"No warning messages were logged: {messages}"
        )

