async def ttftt_engine():
    schema_sdl = """
        enum Test {
            Value1
            Value2
            Value3
        }

        type Query {
            enumTest1: Test
            enumTest2: Test
            enumTest3: Test
        }

        directive @switchValue(oldValue: Test, newValue: Test) on ENUM | ENUM_VALUE

        extend enum Test @switchValue(oldValue: Value2, newValue: ExtendedValue5) {
            ExtendedValue4 @switchValue(newValue: EXTENDEDVALUE7)
            ExtendedValue5
            ExtendedValue6
            EXTENDEDVALUE7
        }

        enum anEnum {
            A
        }

        extend enum anEnum @switchValue
    """

    @Directive(name="switchValue", schema_name="test_issue_278_enum_extend")
    class SwitchValue:
        @staticmethod
        async def on_pre_output_coercion(
            directive_args: Dict[str, Any],
            next_directive: Callable,
            value: Any,
            ctx: Optional[Any],
            info: "ResolveInfo",
        ):
            value = await next_directive(value, ctx, info)
            if value == directive_args.get("oldValue"):
                return directive_args["newValue"]

            if not directive_args.get("oldValue"):
                return directive_args["newValue"]

            return value

    @Resolver("Query.enumTest1", schema_name="test_issue_278_enum_extend")
    async def resolver_enum_test_1(*args, **kwargs):
        return "Value2"

    @Resolver("Query.enumTest2", schema_name="test_issue_278_enum_extend")
    async def resolver_enum_test_2(*args, **kwargs):
        return "ExtendedValue4"

    @Resolver("Query.enumTest3", schema_name="test_issue_278_enum_extend")
    async def resolver_enum_test_3(*args, **kwargs):
        return "ExtendedValue6"

    return await create_engine(
        schema_sdl, schema_name="test_issue_278_enum_extend"
    )

async def ttftt_engine():
    schema_sdl = """
        input anInput {
            a: String
            b: Float
        }

        type Query {
            test1(aParameter: anInput): String
        }

        input switchValuInput {
            c: Int
        }

        input anotherInput {
            g: Int
        }

        directive @switchValue(newValue: switchValuInput) on INPUT_OBJECT

        extend input anInput @switchValue(newValue: {c: 5}) {
            c: Int
        }

        extend input anotherInput @switchValue(newValue: switchValuInput)
    """

    @Directive(
        name="switchValue", schema_name="test_issue_278_input_object_extend"
    )
    class SwitchValue:
        async def on_post_input_coercion(
            self,
            directive_args: Dict[str, Any],
            next_directive: Callable,
            parent_node,
            value: Any,
            ctx: Optional[Any],
        ):
            value = await next_directive(parent_node, value, ctx)
            value.update(directive_args["newValue"])
            return value

    @Resolver("Query.test1", schema_name="test_issue_278_input_object_extend")
    async def resolver_input_object_test_1(_pr, arguments, *_args, **_kwargs):
        return str(arguments)

    return await create_engine(
        schema_sdl, schema_name="test_issue_278_input_object_extend"
    )

async def ttftt_engine():
    schema_sdl = """
        type Query {
