def model(request):
    A, B = request.param

    class _Model:
        def __init__(self, A, B):
            self.A = A
            self.B = B
            self.n_called = 0

        async def __call__(self, input_list):
            self.n_called += 1
            await asyncio.sleep(self.B + self.A * len(input_list))
            return [i * 2 for i in input_list]

    return _Model(A, B)

