def mock_whale_dir(monkeypatch, tmp_path, request):
    is_path_creation_enabed = request.param
    for attr_name, path in {
        "BASE_DIR": paths.BASE_DIR,
        "CONFIG_DIR": paths.CONFIG_DIR,
        "CONNECTION_PATH": paths.CONNECTION_PATH,
        "LOGS_DIR": paths.LOGS_DIR,
        "MANIFEST_DIR": paths.MANIFEST_DIR,
        "MANIFEST_PATH": paths.MANIFEST_PATH,
        "METRICS_PATH": paths.METRICS_PATH,
        "METADATA_PATH": paths.METADATA_PATH,
        "TEMPLATE_DIR": paths.TEMPLATE_DIR,
    }.items():
        d = get_mocked_path(tmp_path, path)
        monkeypatch.setattr(paths, attr_name, d)

        if is_path_creation_enabed:
            if d.is_dir():
                d.parent.mkdir(parents=True, exist_ok=True)
            elif d.is_file():
                d.touch(exist_ok=True)
        if attr_name in ["TEMPLATE_DIR"]:
            monkeypatch.setattr(sql, attr_name, d)
    return tmp_path

def patched_config(tmp_path):
    metadata_subpath = paths.get_subdir_without_whale(str(paths.METADATA_PATH))
    tmp_manifest_subpath = paths.get_subdir_without_whale(str(paths.TMP_MANIFEST_PATH))
    new_metadata_path = tmp_path / metadata_subpath
    new_metadata_path.mkdir()
    new_tmp_manifest_path = tmp_path / tmp_manifest_subpath
    new_tmp_manifest_path.parent.mkdir()

    return ConfigFactory.from_dict(
        {
            "base_directory": tmp_path / metadata_subpath,
            "tmp_manifest_path": tmp_path / tmp_manifest_subpath,
        }
    )

def uds() -> typing.Iterator[str]:
    uds = "test_server.sock"
    try:
        yield uds
    finally:
        os.remove(uds)

def uds_server(uds: str) -> typing.Iterator[Server]:
    if hypercorn is not None:
        server = HypercornServer(app=app, bind=f"unix:{uds}")
        with server.serve_in_thread():
            yield server
    else:
        # On Python 3.6, use Uvicorn as a fallback.
        import uvicorn

        class UvicornServer(Server, uvicorn.Server):
            sends_reason = True

            @property
            def uds(self) -> str:
                uds = self.config.uds
                assert uds is not None
                return uds

            def install_signal_handlers(self) -> None:
                pass

            @contextlib.contextmanager
            def serve_in_thread(self) -> typing.Iterator[None]:
                thread = threading.Thread(target=self.run)
                thread.start()
                try:
                    while not self.started:
                        time.sleep(1e-3)
                    yield
                finally:
                    self.should_exit = True
                    thread.join()

        config = uvicorn.Config(app=app, lifespan="off", loop="asyncio", uds=uds)
        server = UvicornServer(config=config)
        with server.serve_in_thread():
            yield server

