def init_node_instances(node_infos):
    jobs = []

    # Init Grid Nodes
    for (node_id, port) in node_infos:
        p = Process(target=setUpPyGrid, args=(port, node_id))
        p.start()

        import requests

        requests.post(
            os.path.join("http://localhost:" + GRID_NETWORK_PORT, "join"),
            data=json.dumps(
                {"node-id": node_id, "node-address": "http://localhost:" + port}
            ),
        )

        time.sleep(2)
        jobs.append(p)

    yield

    for job in jobs:
        job.terminate()

def hook():
    hook = syft.TorchHook(torch)
    return hook

def connected_node(hook):
    nodes = {}
    for (node_id, port) in zip(IDS, PORTS):
        node = create_websocket_client(hook, port, node_id)
        nodes[node_id] = node

    yield nodes

    for node in nodes:
        nodes[node].close()
        time.sleep(0.1)

def cai_dump_file_gcs_paths(request):
    path = request.config.getoption('--cai_dump_file_gcs_paths')
    path = path.replace('[', '').replace(']', '')
    path = path.replace("'", '').replace(' ', '')
    return path.split(',')

def cloudsql_connection(cloudsql_password, cloudsql_port, cloudsql_username):
    yield create_engine(
            f'mysql+pymysql://{cloudsql_username}:{cloudsql_password}@127.0.0.1:{cloudsql_port}')

