def sa(test_backends):
    if (
        "postgresql" not in test_backends
        and "sqlite" not in test_backends
        and "mysql" not in test_backends
        and "mssql" not in test_backends
    ):
        pytest.skip("No recognized sqlalchemy backend selected.")
