def setUp(self):
        super().setUp()
        try:
            with open("/proc/self/cgroup", "rb") as f:
                for line in f:
                    if line.startswith(b"0::"):
                        self.cgroup = line[3:].rstrip(b"\n")
                        break
                else:
                    self.skipTest("process is not using cgroup v2")
        except FileNotFoundError:
            self.skipTest("kernel does not support cgroup")

