def setUpClass(cls):
        FinalABCMeta = compose_types(FinalMeta, ABCMeta)

        class ABCWithFinal(with_metaclass(FinalABCMeta, object)):
            a = final('ABCWithFinal: a')
            b = 'ABCWithFinal: b'

            @final
            def f(self):
                return 'ABCWithFinal: f'

            def g(self):
                return 'ABCWithFinal: g'

            @abstractmethod
            def h(self):
                raise NotImplementedError('h')

        cls.class_ = ABCWithFinal

def temp_file_creator(temp_dir):
    """Create a function that makes a temp file in a fixture."""
    temp_files = []

    def create_temp_file():
        """Create a temp file for each function invocation."""
        tmp = tempfile.NamedTemporaryFile(dir=temp_dir)
        temp_files.append(tmp)
        return Path(tmp.name)

    yield create_temp_file

    # this runs after the decorated test goes out of scope
    for file in temp_files:
        try:
            # calling close on NamedTemporaryFile removes it
            file.close()
        except FileNotFoundError:
            # maybe the decorated test got rid of it already, no harm no foul.
            pass

def ipyparallel_executor():
    from ipyparallel import Client

    if os.name == "nt":
        import wexpect as expect
    else:
        import pexpect as expect

    child = expect.spawn("ipcluster start -n 1")
    child.expect("Engines appear to have started successfully", timeout=35)
    yield Client()
    if not child.terminate(force=True):
        raise RuntimeError("Could not stop ipcluster")

