def get_record():
    def _get_record(input_q, timeout=None):
        try:
            i = input_q.get(timeout=timeout)
        except queue.Empty:
            return None
        return i

    return _get_record

def start_send_thread(sender_q, get_record):
    stop_event = threading.Event()

    def start_send(send_manager):
        def target():
            while True:
                payload = get_record(input_q=sender_q, timeout=0.1)
                if payload:
                    send_manager.send(payload)
                elif stop_event.is_set():
                    break

        t = threading.Thread(target=target)
        t.daemon = True
        t.start()

    yield start_send
    stop_event.set()

def start_handle_thread(record_q, get_record):
    stop_event = threading.Event()

    def start_handle(handle_manager):
        def target():
            while True:
                payload = get_record(input_q=record_q, timeout=0.1)
                if payload:
                    handle_manager.handle(payload)
                elif stop_event.is_set():
                    break

        t = threading.Thread(target=target)
        t.daemon = True
        t.start()

    yield start_handle
    stop_event.set()

def start_backend(
    mocked_run, hm, sm, sender, start_handle_thread, start_send_thread,
):
    def start_backend_func(initial_run=True):
        start_handle_thread(hm)
        start_send_thread(sm)
        if initial_run:
            _ = sender.communicate_run(mocked_run)

    yield start_backend_func

def stop_backend(
    mocked_run, hm, sm, sender, start_handle_thread, start_send_thread,
):
    def stop_backend_func():
        sender.communicate_exit(0, timeout=5)

    yield stop_backend_func

def typedef_schema():
    return Client(type_def='''
schema {
  query: Query
}

interface Character {
  appearsIn: [Episode]
  friends: [Character]
  id: String!
  name: String
}

type Droid implements Character {
  appearsIn: [Episode]
  friends: [Character]
  id: String!
  name: String
  primaryFunction: String
}

enum Episode {
  EMPIRE
  JEDI
  NEWHOPE
}

type Human implements Character {
  appearsIn: [Episode]
  friends: [Character]
  homePlanet: String
  id: String!
  name: String
}

type Query {
  droid(id: String!): Droid
  hero(episode: Episode): Character
  human(id: String!): Human
}''')

def client():
