            URL,
            headers={
                'Host': 'swapi.graphene-python.org',
                'Accept': 'text/html',
            }
        )
        request.raise_for_status()
        csrf = request.cookies['csrftoken']

        return Client(
            transport=RequestsHTTPTransport(
                url=URL,
                cookies={"csrftoken": csrf},
                headers={'x-csrftoken':  csrf}),
            fetch_schema_from_transport=True
        )

